async function removeEdgeBackground(tolerance = 36) {
  if (!master || !mask) return;
  snapshot();
  const width = master.naturalWidth;
  const height = master.naturalHeight;
  const probe = new OffscreenCanvas(width, height);
  const probeContext = probe.getContext('2d', { willReadFrequently: true });
  probeContext.drawImage(master, 0, 0);
  const pixels = probeContext.getImageData(0, 0, width, height).data;
  const visited = new Uint8Array(width * height);
  const queue = [];
  const seeds = [[0, 0], [width - 1, 0], [0, height - 1], [width - 1, height - 1]];
  const references = seeds.map(([x, y]) => {
    const index = (y * width + x) * 4;
    return [pixels[index], pixels[index + 1], pixels[index + 2]];
  });
  for (const [x, y] of seeds) queue.push(y * width + x);
  let cursor = 0;
  while (cursor < queue.length) {
    const index = queue[cursor++];
    if (visited[index]) continue;
    const x = index % width;
    const y = Math.floor(index / width);
    const pixelIndex = index * 4;
    const matches = references.some(reference => Math.max(
      Math.abs(pixels[pixelIndex] - reference[0]),
      Math.abs(pixels[pixelIndex + 1] - reference[1]),
      Math.abs(pixels[pixelIndex + 2] - reference[2])
    ) <= tolerance);
    if (!matches) continue;
    visited[index] = 1;
    mask.data[pixelIndex + 3] = 0;
    if (x > 0) queue.push(index - 1);
    if (x + 1 < width) queue.push(index + 1);
    if (y > 0) queue.push(index - width);
    if (y + 1 < height) queue.push(index + width);
  }
  await persistMask();
  dirty();
  draw();
  toast('Connected edge background removed non-destructively');
}
